        if cur:
            blocks.append(cur)
            cur = []
        continue
    cur.append(s)
if cur:
    blocks.append(cur)

cn2en = to_dict(blocks[0])
en2dk = to_dict(blocks[1])
word = blocks[2][0]
try:
    print(en2dk[cn2en[word]])
except KeyError:
    print("word not found")

