import sys

rows = [l.strip() for l in sys.stdin.read().splitlines()]
cut = rows.index("")
pairs = [r for r in rows[:cut] if r]
query = next(r for r in rows[cut:] if r)

count = {}
for r in pairs:
    name = r.split(";")[1]
    count[name] = count.get(name, 0) + 1

