scores = []
for token in sys.stdin.read().split():
    value = int(token)
    if value < 0:
        break
    scores.append(value)

if not scores:
    print("no students")
else:
    print("average={:.2f}, failed={}".format(
        sum(scores) / len(scores),
        sum(1 for s in scores if s < 60)))
